31	import org.springframework.http.HttpHeaders;
32	import org.springframework.http.HttpStatus;
33	import org.springframework.http.ResponseEntity;
34	import org.springframework.samples.petclinic.mapper.OwnerMapper;
35	import org.springframework.samples.petclinic.mapper.PetMapper;
36	import org.springframework.samples.petclinic.mapper.VisitMapper;
37	import org.springframework.samples.petclinic.model.Owner;
38	import org.springframework.samples.petclinic.model.Pet;
39	import org.springframework.samples.petclinic.model.Visit;
40	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerHouseholdException;
41	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
42	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
43	import org.springframework.samples.petclinic.rest.advice.MissingOwnerFieldsException;
44	import org.springframework.samples.petclinic.rest.advice.OwnerCityCapacityExceededException;
45	import org.springframework.samples.petclinic.rest.advice.OwnerDailyLimitExceededException;
46	import org.springframework.samples.petclinic.rest.api.OwnersApi;
47	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
48	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
49	import org.springframework.samples.petclinic.rest.dto.PetDto;
50	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
51	import org.springframework.samples.petclinic.rest.dto.VisitDto;
52	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
53	import org.springframework.samples.petclinic.service.ClinicService;
54	import org.springframework.security.access.prepost.PreAuthorize;
55	import org.springframework.web.bind.annotation.CrossOrigin;
56	import org.springframework.web.bind.annotation.RequestMapping;
57	import org.springframework.web.bind.annotation.RestController;
58	import org.springframework.web.util.UriComponentsBuilder;
59	
60	import jakarta.transaction.Transactional;
61	
62	/**
63	 * @author Vitaliy Fedoriv
64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Syntactic check for an email address: a non-empty local part, an '@', a domain with at least
73	     * one dot and a two-or-more letter top-level label. Case-insensitive; the accepted value is
74	     * stored lower-cased.
75	     */
76	    private static final Pattern EMAIL_PATTERN =
77	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
78	
79	    /** Dedicated audit logger; one line is emitted per successful owner create. */
80	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
81	
82	    /**
83	     * The maximum number of owners a single city may contain. Once a city already holds this many
84	     * owners, any further create naming that city is rejected as a conflict.
85	     */
86	    private static final int MAX_OWNERS_PER_CITY = 50;
87	
88	    /**
89	     * The maximum number of owners that may be registered in a single day. Once this many owners
90	     * already carry today's registration date, any further create is rejected as too many requests.
91	     */
92	    private static final int MAX_OWNERS_PER_DAY = 100;
93	
94	    private final ClinicService clinicService;
95	
96	    private final OwnerMapper ownerMapper;
97	
98	    private final PetMapper petMapper;
99	
100	    private final VisitMapper visitMapper;
101	
102	    public OwnerRestControllerV1(ClinicService clinicService,
103	                                 OwnerMapper ownerMapper,
104	                                 PetMapper petMapper,
105	                                 VisitMapper visitMapper) {
106	        this.clinicService = clinicService;
107	        this.ownerMapper = ownerMapper;
108	        this.petMapper = petMapper;
109	        this.visitMapper = visitMapper;
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
115	        Collection<Owner> owners;
116	        if (lastName != null) {
117	            owners = this.clinicService.findOwnerByLastName(lastName);
118	        } else {
119	            owners = this.clinicService.findAllOwners();
120	        }
121	        if (owners.isEmpty()) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
130	        Owner owner = this.clinicService.findOwnerById(ownerId);
131	        if (owner == null) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
140	        validateRequiredOwnerFields(ownerFieldsDto);
141	        LocalDate suppliedOrDefaultDate =
142	            ownerFieldsDto.getRegistrationDate() != null ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
143	        LocalDate registrationDate = toBusinessDay(suppliedOrDefaultDate);
144	        rejectDailyLimitExceeded(registrationDate);
145	        rejectCityAtCapacity(ownerFieldsDto.getCity());
146	        HttpHeaders headers = new HttpHeaders();
147	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
148	        owner.setAddress(normalizeAddress(owner.getAddress()));
149	        String normalizedTelephone = normalizeTelephone(owner.getTelephone());
150	        owner.setTelephone(normalizedTelephone);
151	        rejectDuplicateTelephone(normalizedTelephone);
152	        applyHousehold(owner, ownerFieldsDto.getSharesHousehold());
153	        owner.setEmail(normalizeEmail(owner.getEmail()));
154	        owner.setRegistrationDate(registrationDate);
155	        owner.setCustomerCode(generateCustomerCode(owner.getCity(), owner.getLastName()));
156	        owner.setMembershipNumber(generateMembershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
157	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
158	        this.clinicService.saveOwner(owner);
159	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={}",
160	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
161	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
162	        headers.setLocation(UriComponentsBuilder.newInstance()
163	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
164	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
170	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
171	        if (currentOwner == null) {
172	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
173	        }
174	        currentOwner.setAddress(ownerFieldsDto.getAddress());
175	        currentOwner.setCity(ownerFieldsDto.getCity());
176	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
177	        currentOwner.setLastName(ownerFieldsDto.getLastName());
178	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
179	        this.clinicService.saveOwner(currentOwner);
180	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Transactional
185	    @Override
186	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
187	        Owner owner = this.clinicService.findOwnerById(ownerId);
188	        if (owner == null) {
189	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	        }
191	        this.clinicService.deleteOwner(owner);
192	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
193	    }
194	
195	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
196	    @Override
197	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
198	        Owner owner = this.clinicService.findOwnerById(ownerId);
199	        if (owner == null) {
200	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
201	        }
202	        HttpHeaders headers = new HttpHeaders();
203	        Pet pet = petMapper.toPet(petFieldsDto);
204	        owner.setId(ownerId);
205	        pet.setOwner(owner);
206	        pet.getType().setName(null);
207	        this.clinicService.savePet(pet);
208	        PetDto petDto = petMapper.toPetDto(pet);
209	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
210	            .buildAndExpand(pet.getId()).toUri());
211	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
212	    }
213	
214	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
215	    @Override
216	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
217	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
218	        if (currentOwner != null) {
219	            Pet currentPet = this.clinicService.findPetById(petId);
220	            if (currentPet != null) {
221	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
222	                currentPet.setName(petFieldsDto.getName());
223	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
224	                this.clinicService.savePet(currentPet);
225	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
226	            }
227	        }
228	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
229	    }
230	
231	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
232	    @Override
233	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
234	        HttpHeaders headers = new HttpHeaders();
235	        Visit visit = visitMapper.toVisit(visitFieldsDto);
236	        Pet pet = new Pet();
237	        pet.setId(petId);
238	        visit.setPet(pet);
239	        this.clinicService.saveVisit(visit);
240	        VisitDto visitDto = visitMapper.toVisitDto(visit);
241	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
242	            .buildAndExpand(visit.getId()).toUri());
243	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
244	    }
245	
246	
247	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
248	    @Override
249	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
250	        Owner owner = this.clinicService.findOwnerById(ownerId);
251	        if (owner != null) {
252	            Pet pet = owner.getPet(petId);
253	            if (pet != null) {
254	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
255	            }
256	        }
257	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
258	    }
259	
260	    /**
261	     * Rejects an owner whose mandatory fields are missing (null) or blank. The name of every
262	     * offending field is collected so the caller learns exactly which values must be supplied.
263	     *
264	     * @param ownerFieldsDto the submitted owner payload
265	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or
266	     *         telephone is missing or blank
267	     */
268	    private void validateRequiredOwnerFields(OwnerFieldsDto ownerFieldsDto) {
269	        List<String> missingFields = new ArrayList<>();
270	        if (isBlank(ownerFieldsDto.getFirstName())) {
271	            missingFields.add("firstName");
272	        }
273	        if (isBlank(ownerFieldsDto.getLastName())) {
274	            missingFields.add("lastName");
275	        }
276	        if (isBlank(normalizeAddress(ownerFieldsDto.getAddress()))) {
277	            missingFields.add("address");
278	        }
279	        if (isBlank(ownerFieldsDto.getCity())) {
280	            missingFields.add("city");
281	        }
282	        if (isBlank(ownerFieldsDto.getTelephone())) {
283	            missingFields.add("telephone");
284	        }
285	        if (!missingFields.isEmpty()) {
286	            throw new MissingOwnerFieldsException(missingFields);
287	        }
288	    }
289	
290	    private boolean isBlank(String value) {
291	        return value == null || value.isBlank();
292	    }
293	
294	    /**
295	     * Counts the existing owners who, before this create, already share the given first and last name.
296	     * Both names are compared case-insensitively (after trimming surrounding whitespace and collapsing
297	     * internal runs of whitespace, mirroring the other name comparisons), so cosmetic differences in
298	     * case or spacing still count as the same name.
299	     *
300	     * @param firstName the first name of the owner being created
301	     * @param lastName the last name of the owner being created
302	     * @return the number of existing owners sharing both names (zero when none)
303	     */
304	    private int countNamesakes(String firstName, String lastName) {
305	        String first = normalizeHouseholdField(firstName);
306	        String last = normalizeHouseholdField(lastName);
307	        return (int) this.clinicService.findAllOwners().stream()
308	            .filter(existing -> normalizeHouseholdField(existing.getFirstName()).equals(first)
309	                && normalizeHouseholdField(existing.getLastName()).equals(last))
310	            .count();
311	    }
312	
313	    /**
314	     * Rejects an owner create whose city already holds the maximum number of owners. Owners are
315	     * grouped into a city case-insensitively after surrounding whitespace is trimmed and internal
316	     * runs are collapsed (mirroring the other city comparisons), so cosmetic differences in case or
317	     * spacing count as the same city. When the city already contains {@link #MAX_OWNERS_PER_CITY} or
318	     * more owners the create is rejected as a conflict.
319	     *
320	     * @param city the city of the owner being created
321	     * @throws OwnerCityCapacityExceededException if the city already contains the maximum number of owners
322	     */
323	    /**
324	     * Rejects an owner create once the maximum number of owners have already been registered on the
325	     * business day this owner would land on. Owners are grouped by their {@code registrationDate},
326	     * which is always a business day (a weekend effective date is rolled forward to the following
327	     * Monday); when {@link #MAX_OWNERS_PER_DAY} or more existing owners already carry the given
328	     * business day the create is rejected as too many requests. Because a weekend effective date is
329	     * rolled forward, this quota bounds the number of owners that may be registered per business day.
330	     *
331	     * @param businessDay the adjusted business day the owner being created would be registered on
332	     * @throws OwnerDailyLimitExceededException if the business day already holds the maximum number of owners
333	     */
334	    private void rejectDailyLimitExceeded(LocalDate businessDay) {
335	        long ownersOnDay = this.clinicService.findAllOwners().stream()
336	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
337	            .count();
338	        if (ownersOnDay >= MAX_OWNERS_PER_DAY) {
339	            throw new OwnerDailyLimitExceededException(businessDay, MAX_OWNERS_PER_DAY);
340	        }
341	    }
342	
343	    /**
344	     * Rolls an effective registration date forward onto a business day. A Saturday or Sunday is moved
345	     * forward to the following Monday; a weekday is returned unchanged. This applies whether the date
346	     * was supplied on the request or defaulted to the server's current date.
347	     *
348	     * @param date the effective registration date (supplied or defaulted)
349	     * @return the same date when it is a weekday, otherwise the following Monday
350	     */
351	    private LocalDate toBusinessDay(LocalDate date) {
352	        return switch (date.getDayOfWeek()) {
353	            case SATURDAY -> date.plusDays(2);
354	            case SUNDAY -> date.plusDays(1);
355	            default -> date;
356	        };
357	    }
358	
359	    private void rejectCityAtCapacity(String city) {
360	        String normalizedCity = normalizeHouseholdField(city);
361	        long ownersInCity = this.clinicService.findAllOwners().stream()
362	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
363	            .count();
364	        if (ownersInCity >= MAX_OWNERS_PER_CITY) {
365	            throw new OwnerCityCapacityExceededException(city, MAX_OWNERS_PER_CITY);
366	        }
367	    }
368	
369	    /**
370	     * Builds an owner's customer code, formatted '&lt;CITY3&gt;-&lt;LAST3&gt;-&lt;NNNN&gt;'. CITY3 is
371	     * the upper-cased first three letters of the city; LAST3 is the upper-cased first three letters of
372	     * the last name; NNNN is a per-city 4-digit zero-padded sequence equal to one more than the number
373	     * of owners already in that city (e.g. 'SYD-SMI-0007').
374	     *
375	     * @param city the owner's city
376	     * @param lastName the owner's last name
377	     * @return the formatted customer code
378	     */
379	    private String generateCustomerCode(String city, String lastName) {
380	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
381	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
382	        String normalizedCity = normalizeHouseholdField(city);
383	        int sequence = (int) this.clinicService.findAllOwners().stream()
384	            .filter(existing -> normalizeHouseholdField(existing.getCity()).equals(normalizedCity))
385	            .count() + 1;
386	        return String.format("%s-%s-%04d", city3, last3, sequence);
387	    }
388	
389	    /**
390	     * Builds an owner's membership number, formatted '&lt;customerCode&gt;-M&lt;YY&gt;' where
391	     * customerCode is the owner's customer code and YY is the last two digits of the
392	     * registrationDate year (e.g. 'SMI-0007-M26').
393	     *
394	     * @param customerCode the owner's customer code
395	     * @param registrationDate the owner's registration date
396	     * @return the formatted membership number
397	     */
398	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
399	        String yy = String.format("%02d", registrationDate.getYear() % 100);
400	        return customerCode + "-M" + yy;
401	    }
402	
403	    /**
404	     * Normalizes a telephone number supplied on create into E.164 form. Spaces, dashes and brackets
405	     * are stripped. When the value carries an explicit leading '+' its country code is kept as given;
406	     * otherwise country code '+61' is assumed and a single leading '0' is dropped from the national
407	     * digits. The result must be a '+' followed by 8 to 15 digits. This E.164 string is what gets
408	     * stored and returned.
409	     *
410	     * @param telephone the raw telephone value from the request
411	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
412	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
413	     */
414	    private String normalizeTelephone(String telephone) {
415	        String cleaned = telephone == null ? "" : telephone.trim().replaceAll("[\\s()\\-]", "");
416	        String e164;
417	        if (cleaned.startsWith("+")) {
418	            e164 = cleaned;
419	        } else {
420	            String national = cleaned;
421	            if (national.startsWith("0")) {
422	                national = national.substring(1);
423	            }
424	            e164 = "+61" + national;
425	        }
426	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
427	            throw new InvalidOwnerFieldsException(List.of("telephone"));
428	        }
429	        return e164;
430	    }
431	
432	    /**
433	     * Normalizes an optional email address supplied on create. An absent email (null or blank) is
434	     * left unset. When a value is present it must be a syntactically valid address; the normalized
435	     * form stored and returned is the value lower-cased.
436	     *
437	     * @param email the raw email value from the request, or {@code null} when none was supplied
438	     * @return the lower-cased email, or {@code null} when no email was supplied
439	     * @throws InvalidOwnerFieldsException if a non-blank value is not a syntactically valid address
440	     */
441	    private String normalizeEmail(String email) {
442	        if (email == null || email.isBlank()) {
443	            return null;
444	        }
445	        if (!EMAIL_PATTERN.matcher(email).matches()) {
446	            throw new InvalidOwnerFieldsException(List.of("email"));
447	        }
448	        return email.toLowerCase(Locale.ROOT);
449	    }
450	
451	    /**
452	     * Normalizes an address supplied on create. Surrounding whitespace is trimmed, each internal run
453	     * of whitespace is collapsed to a single space, the value is upper-cased and common abbreviations
454	     * are expanded to their full words (ST -&gt; STREET, RD -&gt; ROAD, AVE -&gt; AVENUE). This
455	     * normalized form is what gets stored, returned and used for every address comparison (the
456	     * required-field check, household duplicate detection and the shared household id).
457	     *
458	     * @param address the raw address value from the request, or {@code null}
459	     * @return the normalized address (empty string when {@code address} is {@code null} or blank)
460	     */
461	    private String normalizeAddress(String address) {
462	        if (address == null) {
463	            return "";
464	        }
465	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
466	        if (collapsed.isEmpty()) {
467	            return "";
468	        }
469	        String[] tokens = collapsed.split(" ");
470	        for (int i = 0; i < tokens.length; i++) {
471	            switch (tokens[i]) {
472	                case "ST" -> tokens[i] = "STREET";
473	                case "RD" -> tokens[i] = "ROAD";
474	                case "AVE" -> tokens[i] = "AVENUE";
475	                default -> { }
476	            }
477	        }
478	        return String.join(" ", tokens);
479	    }
480	
481	    /**
482	     * Rejects an owner create whose E.164 telephone is already used by any other owner. Owners store
483	     * their telephone in E.164 form, so the uniqueness check compares these canonical E.164 values
484	     * directly and is therefore independent of the punctuation a caller supplied.
485	     *
486	     * @param e164Telephone the E.164 telephone of the owner being created
487	     * @throws DuplicateOwnerTelephoneException if another owner already uses this telephone
488	     */
489	    private void rejectDuplicateTelephone(String e164Telephone) {
490	        boolean inUse = this.clinicService.findAllOwners().stream()
491	            .map(Owner::getTelephone)
492	            .filter(existing -> existing != null)
493	            .anyMatch(e164Telephone::equals);
494	        if (inUse) {
495	            throw new DuplicateOwnerTelephoneException(e164Telephone);
496	        }
497	    }
498	
499	    /**
500	     * Applies the household rule to an owner being created. A household is the set of owners sharing a
501	     * last name and a normalized address: last names are compared case-insensitively after whitespace
502	     * is trimmed and collapsed, and addresses are compared in their normalized form (see
503	     * {@link #normalizeAddress(String)}), so purely cosmetic differences in spacing, letter case or
504	     * abbreviation still count as the same household.
505	     * <p>
506	     * When the owner's last name and address already belong to at least one other owner the behaviour
507	     * depends on {@code sharesHousehold}. If it is not true the create is rejected as a duplicate
508	     * household. If it is true the create is allowed and every member of the household - the existing
509	     * owners and this joiner - is assigned the same stable {@code householdId}, which is returned on
510	     * read. When no other owner shares the last name and address no identifier is assigned.
511	     *
512	     * @param owner the owner being created
513	     * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
514	     * @throws DuplicateOwnerHouseholdException if another owner already shares this last name and
515	     *         address and {@code sharesHousehold} is not true
516	     */
517	    private void applyHousehold(Owner owner, Boolean sharesHousehold) {
518	        String lastName = normalizeHouseholdField(owner.getLastName());
519	        String address = normalizeAddress(owner.getAddress());
520	        List<Owner> housemates = this.clinicService.findAllOwners().stream()
521	            .filter(existing -> normalizeHouseholdField(existing.getLastName()).equals(lastName)
522	                && normalizeAddress(existing.getAddress()).equals(address))
523	            .toList();
524	        if (housemates.isEmpty()) {
525	            return;
526	        }
527	        if (!Boolean.TRUE.equals(sharesHousehold)) {
528	            throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
529	        }
530	        String householdId = generateHouseholdId(lastName, address);
531	        owner.setHouseholdId(householdId);
532	        for (Owner housemate : housemates) {
533	            if (!householdId.equals(housemate.getHouseholdId())) {
534	                housemate.setHouseholdId(householdId);
535	                this.clinicService.saveOwner(housemate);
536	            }
537	        }
538	    }
539	
540	    /**
541	     * Builds the stable identifier shared by the members of one household. It is derived purely from
542	     * the normalized last name and address, so every owner of a given household deterministically
543	     * resolves to the same value - the first 12 upper-case hex characters of the SHA-256 digest of the
544	     * two normalized fields joined by a single space.
545	     *
546	     * @param normalizedLastName the household's last name, already normalized for comparison
547	     * @param normalizedAddress the household's address, already normalized for comparison
548	     * @return the shared household identifier
549	     */
550	    private String generateHouseholdId(String normalizedLastName, String normalizedAddress) {
551	        String key = normalizedLastName + '�' + normalizedAddress;
552	        try {
553	            byte[] digest = MessageDigest.getInstance("SHA-256")
554	                .digest(key.getBytes(StandardCharsets.UTF_8));
555	            StringBuilder hex = new StringBuilder();
556	            for (byte b : digest) {
557	                hex.append(String.format("%02X", b));
558	                if (hex.length() >= 12) {
559	                    break;
560	                }
561	            }
562	            return hex.substring(0, 12);
563	        } catch (NoSuchAlgorithmException e) {
564	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
565	        }
566	    }
567	
568	    /**
569	     * Normalizes a last name for household comparison: surrounding whitespace is trimmed, each
570	     * internal run of whitespace is collapsed to a single space and the result is lower-cased.
571	     * Addresses use {@link #normalizeAddress(String)} instead, which additionally upper-cases and
572	     * expands common abbreviations.
573	     *
574	     * @param value the raw last name, or {@code null}
575	     * @return the normalized comparison key (empty string when {@code value} is {@code null})
576	     */
577	    private String normalizeHouseholdField(String value) {
578	        if (value == null) {
579	            return "";
580	        }
581	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
582	    }
583	}
